const s=wb.getWorksheet('Sheet1');
const A=['OCOGS - Spares - Transfer Price Overhead','OFSS - ORCL Consulting Prod Cost I/C'],B=['BOA_033E','BOA_011G'];
const out=[];
for(let r=2;r<=45;r++){
 const bl=wb.getRange(`Sheet1!BL${r}`), bg=wb.getRange(`Sheet1!BG${r}`).getCell().getValue(), ay=wb.getRange(`Sheet1!AY${r}`).getCell().getValue();
 const lag=bl.getCell().getValue();
 const hit=lag==='LAG'&&A.includes(bg);
 const looseHit=String(lag).trim().toUpperCase()==='LAG'&&A.map(x=>x.toUpperCase()).includes(String(bg).trim().toUpperCase());
 out.push([r,JSON.stringify(lag),hit,looseHit,B.includes(ay),JSON.stringify(bl.getCell().getStyle?.().getFill?.())].join(' | '));
}
log(out.join('\n'));
log(wb.getWorksheet('Sheet1').getRange('BL1:BL45').getRegions?.('fill'));

